package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.block.Blocks;
import net.minecraft.server.network.*;
import net.minecraft.util.math.*;
/** Remote-city regression in a normal terrain server; no distant chunk is requested by the fixture. */
final class WorldSettlementChecks {
 static VillageProjects.Project local;static boolean localTested;static boolean done,setup;static int age,baselineJobs,baselineChunks;static net.minecraft.server.network.ServerPlayerEntity observer;static final List<BlockPos> remote=new ArrayList<>();static long worst,total;
 static void require(boolean b,String message){if(!b)throw new AssertionError(message);}
 static void register(){if(!Boolean.getBoolean("halloween.worldSettlementTest"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(done||server.getTicks()<40)return;var w=server.getOverworld();try{
 if(!setup){observer=new ServerPlayerEntity(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"CityObserver"),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());observer.networkHandler=new ServerPlayNetworkHandler(server,new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND),observer,ConnectedClientData.createDefault(observer.getGameProfile(),false));observer.setPosition(0,100,0);w.getPlayers().add(observer);var memory=w.getPersistentStateManager().getOrCreate(VillageMemory.TYPE);var cities=WorldSettlements.get(w);var field=net.minecraft.server.world.ServerWorld.class.getDeclaredField("worldProperties");field.setAccessible(true);((net.minecraft.world.level.ServerWorldProperties)field.get(w)).setTime(24000L*100);cities.epoch=0;var jobs=VillageProjects.get(w);
 for(int i=0;i<200;i++){var p=new BlockPos(1_000_000+i*1024,80,1_000_000);remote.add(p);long id=700_000+i;var team=new VillageMemory.Team(id,p,0);memory.teams.add(team);var c=WorldSettlements.discover(w,p);c.catchup=true;c.target=3;var plan=List.of(new VillageCivilWorks.Change(p,Blocks.AIR.getDefaultState(),Blocks.STONE.getDefaultState()));var job=new VillageProjects.Project("lag-fixture:"+i,id,"house",p,p,plan,0,false,0);jobs.jobs.add(job);jobs.expected.put(p,Blocks.STONE.getDefaultState());jobs.unfinished.put(p,1);}
 w.setChunkForced(0,0,true);w.getChunk(0,0);var localPlan=new ArrayList<VillageCivilWorks.Change>();for(int x=8;x<12;x++)for(int z=8;z<12;z++)for(int y=160;y<164;y++){var p=new BlockPos(x,y,z);w.setBlockState(p,Blocks.AIR.getDefaultState());localPlan.add(new VillageCivilWorks.Change(p,Blocks.AIR.getDefaultState(),Blocks.STONE.getDefaultState()));}local=new VillageProjects.Project("loaded-budget-fixture",999999,"house",new BlockPos(8,160,8),new BlockPos(11,163,11),localPlan,0,false,0);jobs.jobs.add(local);for(var change:localPlan){jobs.expected.put(change.pos(),change.after());jobs.unfinished.put(change.pos(),1);}
 baselineJobs=jobs.jobs.size();baselineChunks=w.getChunkManager().getLoadedChunkCount();server.getTickManager().setTickRate(20);setup=true;return;}
 long start=System.nanoTime();WorldSettlements.tick(w);long elapsed=System.nanoTime()-start;total+=elapsed;worst=Math.max(worst,elapsed);age++;
 if(age>=10&&!localTested&&w.isChunkLoaded(new ChunkPos(local.min).toLong())){for(int attempt=0;attempt<10&&local.index==0;attempt++)VillageProjects.materialize(w,999999,32);require(local.index>0&&local.index<=32,"loaded work must advance within one 32-block slice: "+local.index);localTested=true;}
 for(var p:remote)require(!w.isChunkLoaded(new ChunkPos(p).toLong()),"remote estimate loaded a chunk "+p);require(VillageProjects.get(w).jobs.size()==baselineJobs,"remote estimate planned physical buildings");
 if(age>600){require(localTested,"loaded-site fixture must actually load and advance");for(var job:VillageProjects.get(w).jobs)if(job.id.startsWith("lag-fixture:"))require(job.index==0,"remote job materialized");require(WorldSettlements.estimate(w,WorldSettlements.get(w).cities.getLast())>=2.8,"distant development still advances by elapsed time");require(worst<50_000_000,"ledger tick exceeds 50ms: "+worst);require(w.getChunkManager().getLoadedChunkCount()<=baselineChunks+128,"unexpected terrain loading");org.slf4j.LoggerFactory.getLogger("world-settlement-test").info("PASS 200 distant catchup cities: zero remote chunk loads/plans/blocks; loaded work advances in <=32-block slices; estimates advance; ledger avg={}us max={}us; loaded chunks {} -> {}",total/age/1000,worst/1000,baselineChunks,w.getChunkManager().getLoadedChunkCount());done=true;w.getPlayers().remove(observer);server.stop(false);}
 }catch(Throwable e){done=true;org.slf4j.LoggerFactory.getLogger("world-settlement-test").error("FAIL",e);if(observer!=null)w.getPlayers().remove(observer);server.stop(false);}});}
}
